.home-section5-brand {
    --hs5-brand-base: #00519b;
    --hs5-brand-base-rgb: 0, 81, 155;
    --hs5-brand-gray: #4D5756;
    --hs5-brand-black: #081933;
    --hs5-brand-black-rgb: 8, 25, 51;
    --hs5-brand-primary: #f8f4f2;
    --hs5-brand-white: #ffffff;
    --hs5-brand-bdr-color: #ede8e6;
    --hs5-brand-bdr-radius: 5px;
}

.home-section5-brand .brand-one {
    position: relative;
    display: block;
    padding: 120px 0 90px;
    background-color: var(--hs5-brand-primary);
    z-index: 1;
}

.home-section5-brand .section-title {
    position: relative;
    display: block;
    margin-top: -6px;
    margin-bottom: 49px;
    z-index: 1;
}

.home-section5-brand .section-title__tagline-box {
    position: relative;
    display: inline-flex;
    align-items: center;
    flex-wrap: wrap;
    margin-bottom: 6px;
}

.home-section5-brand .section-title__tagline-shape {
    position: relative;
    display: inline-block;
    width: 15px;
    height: 15px;
    background-color: var(--hs5-brand-base);
    border-radius: 50%;
    clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
}

.home-section5-brand .section-title__tagline-shape-2 {
    position: relative;
    display: inline-block;
    width: 12px;
    height: 12px;
    background-color: var(--hs5-brand-black);
    border-radius: 50%;
    margin-left: -8px;
    clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
}

.home-section5-brand .section-title__tagline {
    position: relative;
    display: block;
    color: var(--hs5-brand-base);
    text-transform: uppercase;
    font-weight: 700;
    font-size: 14px;
    line-height: 14px;
    margin-left: 7px;
}

.home-section5-brand .section-title__title {
    font-size: 42px;
    line-height: 1.2em;
    font-weight: 700;
    color: var(--hs5-brand-black);
    margin: 0;
}

.home-section5-brand .section-title__title span {
    color: var(--hs5-brand-base);
}

.home-section5-brand .brand-one__inner ul {
    position: relative;
    display: flex;
    align-items: stretch;
    flex-wrap: wrap;
    margin-left: -15px;
    margin-right: -15px;
    list-style: none;
    padding: 0;
    margin-bottom: 0;
}

.home-section5-brand .brand-one__inner ul li {
    position: relative;
    text-align: center;
    flex: 0 0 25%;
    max-width: 25%;
    width: 100%;
    margin-bottom: 30px;
    padding-left: 15px;
    padding-right: 15px;
    transition: transform .8s;
}

.home-section5-brand .brand-one__inner ul li:hover {
    transform: translateY(-10px);
}

.home-section5-brand .brand-one__inner ul li > a {
    display: block;
    color: inherit;
    text-decoration: none;
}

.home-section5-brand .brand-one__single {
    position: relative;
    display: block;
    background-color: var(--hs5-brand-bdr-color);
    padding: 25px;
    border-radius: var(--hs5-brand-bdr-radius);
    overflow: hidden;
    z-index: 1;
    min-height: 130px;
}

.home-section5-brand .brand-one__single::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: var(--hs5-brand-white);
    transition-delay: .1s;
    transition-timing-function: ease-in-out;
    transition-duration: .5s;
    transition-property: all;
    transform-origin: top;
    transform-style: preserve-3d;
    transform: scaleX(0);
    z-index: -1;
}

.home-section5-brand .brand-one__inner ul li:hover .brand-one__single::before {
    transform: scaleX(1.0);
}

.home-section5-brand .brand-one__img {
    position: relative;
    display: block;
    max-width: 150px;
    width: 100%;
    margin: 0 auto;
}

.home-section5-brand .brand-one__img img {
    width: 100%;
    height: auto;
    max-height: 90px;
    object-fit: contain;
    margin: 0 auto;
}

.home-section5-brand .brand-one__card-title {
    margin: 12px 0 0;
    font-size: 13px;
    line-height: 1.35;
    font-weight: 600;
    color: var(--hs5-brand-black);
}

.home-section5-brand .brand-one__shape-1 {
    position: absolute;
    bottom: -2px;
    right: 13px;
    border-bottom: 50px solid rgba(var(--hs5-brand-black-rgb), .20);
    border-left: 50px solid transparent;
    border-radius: var(--hs5-brand-bdr-radius);
    z-index: -1;
    pointer-events: none;
}

.home-section5-brand .brand-one__shape-2 {
    position: absolute;
    bottom: -2px;
    left: 13px;
    border-bottom: 50px solid rgba(var(--hs5-brand-black-rgb), .20);
    border-right: 50px solid transparent;
    border-radius: var(--hs5-brand-bdr-radius);
    z-index: -1;
    pointer-events: none;
}

.home-section5-brand .brand-one__shape-3 {
    position: absolute;
    top: -2px;
    right: 13px;
    border-top: 50px solid rgba(var(--hs5-brand-black-rgb), .20);
    border-left: 50px solid transparent;
    border-radius: var(--hs5-brand-bdr-radius);
    z-index: -1;
    pointer-events: none;
}

.home-section5-brand .brand-one__shape-4 {
    position: absolute;
    top: -2px;
    left: 13px;
    border-top: 50px solid rgba(var(--hs5-brand-black-rgb), .20);
    border-right: 50px solid transparent;
    border-radius: var(--hs5-brand-bdr-radius);
    z-index: -1;
    pointer-events: none;
