using System;
using System.Collections.Generic;
using System.Data;
using System.Web;
using System.Web.UI;
using DCore;
using InformationWeb;
using InformationWebObject;

namespace InformationWeb.Controls.InfomationNew
{
    public partial class Home_Info_Section7 : System.Web.UI.UserControl
    {
        private Dictionary<string, DataRow> dicContent;

        /// <summary>
        /// NodeID cho nhóm "Terminal / Testimonial" (feedback) ở trang chủ.
        /// Theo yêu cầu: id = 353.
        /// </summary>
        private const int TerminalNodeId = 353;

        private const int TerminalTop = 10;

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!Page.IsPostBack)
            {
                LoadData();
                LoadTerminalData();
            }
        }

        private void LoadData()
        {
            dicContent = new Dictionary<string, DataRow>(StringComparer.OrdinalIgnoreCase);

            try
            {
                INFO_Information objInformation = new INFO_Information();
                DataTable dtbData = objInformation.GetDataTable(
                    "INFO_AboutPageContent_List",
                    "@PageCode", "HomePage",
                    "@LanguageID", ResManager.CurrentLanguageID
                );

                if (dtbData == null) return;

                foreach (DataRow drwData in dtbData.Rows)
                {
                    if (drwData.Table.Columns.IndexOf("ContentCode") < 0) continue;
                    if (drwData["ContentCode"] == null || drwData["ContentCode"] == DBNull.Value) continue;

                    string strContentCode = drwData["ContentCode"].ToString();
                    if (!dicContent.ContainsKey(strContentCode))
                        dicContent.Add(strContentCode, drwData);
                }
            }
            catch
            {
                dicContent.Clear();
            }
        }

        protected string C(string strContentCode)
        {
            return GetValue(strContentCode, "Content");
        }

        protected string Img(string strContentCode)
        {
            return GetValue(strContentCode, "ImageUrl");
        }

        protected string Link(string strContentCode)
        {
            return GetValue(strContentCode, "LinkUrl");
        }

        private string GetValue(string strContentCode, string strColumnName)
        {
            if (dicContent == null || string.IsNullOrEmpty(strContentCode) || string.IsNullOrEmpty(strColumnName))
                return string.Empty;

            if (!dicContent.ContainsKey(strContentCode))
                return string.Empty;

            DataRow drwData = dicContent[strContentCode];
            if (drwData == null || drwData.Table.Columns.IndexOf(strColumnName) < 0)
                return string.Empty;

            object objValue = drwData[strColumnName];
            if (objValue == null || objValue == DBNull.Value)
                return string.Empty;

            return objValue.ToString();
        }

        private void LoadTerminalData()
        {
            try
            {
                int languageId = ResManager.CurrentLanguageID;
                INFO_Information info = new INFO_Information();
                DataTable dt = info.GetDataTable(
                    "INFO_Information_SIMS_News",
                    "@LanguageID", languageId,
                    "@NodeID", TerminalNodeId,
                    "@Top", TerminalTop
                );

                if (dt == null || dt.Rows.Count == 0)
                {
                    rptTerminal.DataSource = null;
                    rptTerminal.DataBind();
                    phTerminal.Visible = false;
                    return;
                }

                rptTerminal.DataSource = dt.DefaultView;
                rptTerminal.DataBind();
                phTerminal.Visible = true;
            }
            catch (Exception ex)
            {
                new SystemError(SystemConfig.ConnectionString, "Home_Info_Section7: Lỗi load Terminal/Testimonial (INFO_Information_SIMS_News, NodeID=353)", ex);
                phTerminal.Visible = false;
            }
        }

        protected string GetSlideDelay(int itemIndex)
        {
            string[] delays = { ".3", ".5", ".7" };
            int index = itemIndex % delays.Length;
            return delays[index];
        }

        protected string GetTerminalQuote(object dataItem)
        {
            DataRowView row = dataItem as DataRowView;
            if (row == null)
            {
                return string.Empty;
            }

            return HttpUtility.HtmlEncode(GetStringValue(row, "Brief"));
        }

        protected string GetTerminalName(object dataItem)
        {
            DataRowView row = dataItem as DataRowView;
            if (row == null)
            {
                return string.Empty;
            }

            return HttpUtility.HtmlEncode(GetStringValue(row, "Title"));
        }

        protected string GetTerminalRole(object dataItem)
        {
            DataRowView row = dataItem as DataRowView;
            if (row == null)
            {
                return "Sinh viên";
            }

            string role = GetStringValue(row, "SubTitle");
            if (string.IsNullOrEmpty(role))
            {
                role = GetStringValue(row, "Tag");
            }
            if (string.IsNullOrEmpty(role))
            {
                role = GetStringValue(row, "Source");
            }
            if (string.IsNullOrEmpty(role))
            {
                role = "Sinh viên";
            }

            return HttpUtility.HtmlEncode(role);
        }

        protected string GetTerminalRating(object dataItem)
        {
            DataRowView row = dataItem as DataRowView;
            if (row == null)
            {
                return string.Empty;
            }

            string rating = GetStringValue(row, "Rating");
            if (string.IsNullOrEmpty(rating))
            {
                rating = GetStringValue(row, "Other1");
            }

            return HttpUtility.HtmlEncode(rating);
        }

        protected string GetTerminalAvatar(object dataItem, int itemIndex)
        {
            DataRowView row = dataItem as DataRowView;
            if (row == null)
            {
                return GetDefaultAvatar(itemIndex);
            }

            string url = GetInfoThumb(row);
            if (string.IsNullOrEmpty(url))
            {
                return GetDefaultAvatar(itemIndex);
            }

            return url;
        }

        private static string GetDefaultAvatar(int itemIndex)
        {
            int idx = (itemIndex % 5) + 1;
            return "assets/img/testimonial/testi_2_" + idx + ".png";
        }

        private static string GetInfoThumb(DataRowView row)
        {
            if (row == null)
            {
                return string.Empty;
            }

            int id = ConvertToInt(row, "InformationID");
            string image = GetStringValue(row, "ThumbImageSub");
            if (string.IsNullOrEmpty(image))
            {
                image = GetStringValue(row, "ThumbImage");
            }

            if (string.IsNullOrEmpty(image))
            {
                return string.Empty;
            }

            if (image.StartsWith("/") || image.StartsWith("http"))
            {
                return image;
            }

            string paddedId = "000000" + id;
            string subFolder = "Information" + paddedId.Substring(paddedId.Length - 6);
            return WebGlobal.InformationThumbDirectory + "/" + subFolder + "/" + image;
        }

        private static string GetStringValue(DataRowView row, string columnName)
        {
            if (row != null && row.Row != null && row.Row.Table != null
                && row.Row.Table.Columns.Contains(columnName) && row[columnName] != DBNull.Value)
            {
                return Convert.ToString(row[columnName]).Trim();
            }

            return string.Empty;
        }

        private static int ConvertToInt(DataRowView row, string columnName)
        {
            int value;
            if (int.TryParse(GetStringValue(row, columnName), out value))
            {
                return value;
            }

            return 0;
        }
    }
}

