                return string.Empty;

            object objValue = drwData[strColumnName];
            if (objValue == null || objValue == DBNull.Value)
                return string.Empty;

            return objValue.ToString();
        }

        /// <summary>
        /// NodeID (SIMS) truyền cho store INFO_Information_SIMS_News — nhóm tin tuyển sinh trên SiteMap.
        /// 125 được dùng cho mục Tin tức - sự kiện (Home_Info_Section1); cần đặt đúng Node tuyển sinh theo CMS.
        /// </summary>
        private const int AdmissionsSimsNewsNodeId = 325;

        /// <summary>Số bản ghi tối đa trong slider.</summary>
        private const int NewsTop = 10;

        /// <summary>Ảnh mặc định khi không có thumbnail.</summary>
        private const string DefaultThumb = "/Media/TBTS.png";

        private void LoadAdmissionsNews()
        {
            try
            {
                int languageId = ResManager.CurrentLanguageID;
                INFO_Information info = new INFO_Information();
                DataTable dt = info.GetDataTable(
                    "INFO_Information_SIMS_News",
                    "@LanguageID", languageId,
                    "@NodeID", AdmissionsSimsNewsNodeId,
                    "@Top", NewsTop
                );

                if (dt == null || dt.Rows.Count == 0)
                {
                    rptAdmissionsNews.DataSource = null;
                    rptAdmissionsNews.DataBind();
                    phSectionAdmissions.Visible = false;
                    return;
                }

                rptAdmissionsNews.DataSource = dt;
                rptAdmissionsNews.DataBind();
                phSectionAdmissions.Visible = true;
            }
            catch (Exception ex)
            {
                new SystemError(SystemConfig.ConnectionString, "Home_Info_Section3: Lỗi load thông tin tuyển sinh (INFO_Information_SIMS_News)", ex);
                phSectionAdmissions.Visible = false;
            }
        }

        protected string GetNewsImage(object dataItem)
        {
            DataRowView drv = dataItem as DataRowView;
            if (drv == null)
            {
                return DefaultThumb;
            }

            int id = ConvertToInt(drv, "InformationID");
            string image = GetStringValue(drv, "ThumbImageSub");
            if (string.IsNullOrEmpty(image))
            {
                image = GetStringValue(drv, "ThumbImage");
            }

            if (string.IsNullOrEmpty(image))
            {
                return DefaultThumb;
            }

            if (image.StartsWith("/") || image.StartsWith("http"))
            {
                return image;
            }

            string paddedId = "000000" + id;
            string subFolder = "Information" + paddedId.Substring(paddedId.Length - 6);
            return WebGlobal.InformationThumbDirectory + "/" + subFolder + "/" + image;
        }

        protected string GetNewsUrl(object dataItem)
        {
            DataRowView row = dataItem as DataRowView;
            if (row == null)
            {
                return "#";
            }

            string slug = GetStringValue(row, "InformationLink");
            string categoryLink = GetStringValue(row, "CategoryLink");

            if (string.IsNullOrEmpty(slug) || string.IsNullOrEmpty(categoryLink))
            {
                return "#";
            }

            if (ResManager.CurrentLanguageID == 2)
            {
                return "/en/" + categoryLink + "/" + slug;
            }

            return "/" + categoryLink + "/" + slug;
        }

        protected string GetNewsDate(object dataItem)
        {
            DataRowView row = dataItem as DataRowView;
            if (row == null)
            {
                return string.Empty;
            }

            DateTime dateValue;
            if (TryGetDateTime(row, "DisplayFromDate", out dateValue) || TryGetDateTime(row, "CreatedDate", out dateValue))
            {
                return dateValue.ToString("dd/MM/yyyy");
            }

            return string.Empty;
        }

        protected string GetNewsTitle(object dataItem)
        {
            DataRowView row = dataItem as DataRowView;
            if (row == null)
            {
                return string.Empty;
            }

            return HttpUtility.HtmlEncode(GetStringValue(row, "Title"));
        }

        protected string GetNewsBrief(object dataItem)
        {
            DataRowView row = dataItem as DataRowView;
            if (row == null)
            {
                return string.Empty;
            }

            return HttpUtility.HtmlEncode(GetStringValue(row, "Brief"));
        }

        private static string GetStringValue(DataRowView row, string columnName)
        {
            if (row.Row.Table.Columns.Contains(columnName) && row[columnName] != DBNull.Value)
            {
                return Convert.ToString(row[columnName]).Trim();
            }

            return string.Empty;
        }

        private static int ConvertToInt(DataRowView row, string columnName)
        {
            int value;
            if (int.TryParse(GetStringValue(row, columnName), out value))
            {
                return value;
            }

            return 0;
        }

        private static bool TryGetDateTime(DataRowView row, string columnName, out DateTime value)
        {
            value = DateTime.MinValue;
            if (!row.Row.Table.Columns.Contains(columnName) || row[columnName] == DBNull.Value)
            {
                return false;
            }

            return DateTime.TryParse(Convert.ToString(row[columnName]), out value);
        }
    }
